"""Embed the vendored official WOFF2 without downloading anything at build time."""
import base64
from pathlib import Path
import re

root = Path(__file__).resolve().parents[1]
data = base64.b64encode((root / "assets/PaperMono-Variable.woff2").read_bytes()).decode("ascii")
entry = root / "plugin.js"
source, count = re.subn(r"const FONT_DATA = '[^']*';", f"const FONT_DATA = '{data}';", entry.read_text())
if count != 1:
    raise SystemExit("Expected one FONT_DATA declaration")
entry.write_text(source)
(root.parent / "dashboard/style.css").write_text(
    "/* Generated by desktop/scripts/embed-font.py. Official Paper Mono; license in desktop/assets/OFL.txt. */\n"
    "@font-face{font-family:'Hermes Notify Paper Mono';src:url(data:font/woff2;base64,"
    + data + ") format('woff2');font-style:normal;font-weight:100 800;font-display:swap}\n"
    ".hermes-notify-dashboard{font-family:'Hermes Notify Paper Mono','Paper Mono',ui-monospace,monospace;"
    "font-size:14px;line-height:1.6;padding:1rem;color:var(--color-foreground)}\n"
)
